{
  "purpose": "Bounded synthetic strategic-excerpt probe; no external research or files beyond supplied prompt guidance; no full vision/reviews/adoption.",
  "author_instruction": "Use the current Envision core and its research guidance to produce a short strategic excerpt for each supplied brief: interpret the brief, explore credible future experiences before recommending, explain the choice and a useful path. Around 400 words per case is enough; this is a diagnostic excerpt, not a complete Envision run. Do not perform web research or claim independent review. Sources below are synthetic, not real organizations.",
  "company": {
    "operator": "Aster Instruments owns Fieldnote, a deployed desktop diagnostic viewer. Explore an ambitious future that creates more value for technicians and Aster. Current commercial positioning may evolve; preserve existing signed support obligations. Do not assume a change to our company mission or authorize retiring other products. Available sources follow; no unanswered business decision must be silently made.",
    "sources": [
      {
        "id": "C1",
        "type": "official public website, 2026-10-01, synthetic",
        "text": "Aster Instruments: dependable field measurement. SignalBench is sold through service partners. Fieldnote is marketed as an offline desktop log viewer for SignalBench. Website claims 40% faster diagnosis; methodology and customer results are not provided."
      },
      {
        "id": "C2",
        "type": "operator-provided signed commitment, 2026-10-20, synthetic",
        "text": "Existing customer service contracts require supported offline diagnosis and export compatibility through 2029. Contracts do not prohibit connected or multi-device options. SignalBench hardware safety decisions stay with the certified controller."
      },
      {
        "id": "C3",
        "type": "operator-provided support summary, 2026-10-27, synthetic",
        "text": "Six of ten recent service tickets concern switching between instrument history and a work-order system. This is a selected support sample, not representative demand evidence. Service partners already train technicians; no partner has agreed to distribute a new product."
      },
      {
        "id": "C4",
        "type": "repository capability observation, 2026-10-28, synthetic",
        "text": "Fieldnote currently opens local logs, identifies instrument/version, graphs measurements and exports CSV. No cross-instrument history or work-order integration exists. SignalBench export format and service team ownership are documented interfaces."
      }
    ]
  },
  "standalone": {
    "operator": "Looplist is my personal offline rehearsal planner. I want less fiddling between pieces and a satisfying path to helping other amateur musicians. It has working set-list editing and timers. It has no company, customers or business commitments. I have shared no customer research and do not want a commercialization exercise. Explore the possibility without inventing obligations or demanding company material."
  },
  "questions_before_scoring": [
    "What destination did each excerpt recommend, and why?",
    "Which supplied facts materially changed the recommendation or path?",
    "What obligations, uncertainties and decisions remain, and who owns them?",
    "Is any work proposed irrelevant to the stated beneficiary or brief?"
  ],
  "anchors_after_reconstruction": [
    "Company: a consequential choice uses relevant supplied company facts, with source distinction rather than boilerplate list.",
    "The support sample/public efficiency claim are not treated as proof of demand/outcomes. Offline support and certified-controller boundary remain binding; desktop/offline marketing does not silently prohibit an allowed larger future.",
    "Portfolio/shared interface or partner/ownership dependency is connected to a useful advance without presuming partner participation or authority to change company strategy.",
    "Standalone: usable future/path without company questionnaire, invented corporate context or forced commercial research.",
    "These observations show this bounded execution only; no superiority or market validation claim."
  ],
  "controls": [
    {
      "label": "Control X",
      "text": "Aster promises an offline desktop viewer on its website, so Fieldnote must never serve teams or connect to work orders. The 40% faster diagnosis claim proves customer demand. To unlock growth, the vision hereby retires SignalBench and transfers its safety decisions into Fieldnote."
    },
    {
      "label": "Control Y",
      "text": "Looplist should begin by obtaining its parent company mission, product portfolio, enterprise customer contracts and channel strategy. No roadmap can be written until a buyer and monetization model are chosen."
    }
  ],
  "stop": "One author run on both cases; one reader in staged reconstruction then anchors+controls. Any required outcome unproven returns evidence/options to operator before another batch."
}

